<template>
  <div class="mobile-page"><div class="mobile-head"><b>皖政通</b><span>计划管理任务</span><el-tag size="small" type="success">在线</el-tag></div><div class="summary"><div><b>{{ tasks.length }}</b><span>全部任务</span></div><div><b>{{ pending }}</b><span>待处理</span></div><div><b>{{ done }}</b><span>已完成</span></div></div><div class="tabs"><el-radio-group v-model="tab" size="small"><el-radio-button label="all">全部</el-radio-button><el-radio-button label="todo">待处理</el-radio-button><el-radio-button label="done">已完成</el-radio-button></el-radio-group></div><div v-for="task in filtered" :key="task.id" class="task-card"><div class="task-top"><el-tag size="small" :type="task.type === '督办' ? 'danger' : task.type === '政策' ? 'info' : 'warning'">{{ task.type }}</el-tag><span>{{ task.date }}</span></div><h3>{{ task.title }}</h3><p>{{ task.region }} · {{ task.content }}</p><div class="task-bottom"><el-tag size="small" :type="task.status === '已完成' ? 'success' : 'warning'">{{ task.status }}</el-tag><el-button size="small" type="primary" @click="handle(task)">{{ task.action }}</el-button></div></div></div>
</template>
<script setup>
import { computed, ref } from 'vue'
import { ElMessage } from 'element-plus'
const tab = ref('all'); const tasks = ref([{ id: 7, type: '种植任务', title: '查看2026年第一季度小麦种植任务', region: '太和县旧县镇', content: '已下达种植面积220亩，涉及旧县镇赵多种植大户及关联地块，可通过移动端查看任务详情。', date: '2026-10-20', status: '待处理', action: '查看任务' }, { id: 1, type: '进度填报', title: '完成秋粮收获进度填报', region: '太和县旧县镇', content: '请于今日 18:00 前上报到户到田收获面积。', date: '2026-10-13', status: '待处理', action: '立即填报' }, { id: 2, type: '审核', title: '审核太和县粮食生产任务', region: '太和县', content: '主体关联地块清单已提交，请核验面积。', date: '2026-10-12', status: '待处理', action: '进入审核' }, { id: 3, type: '修正', title: '修正地块作物标注', region: '涡阳县', content: '发现 2 宗地块作物与遥感识别结果不一致。', date: '2026-10-11', status: '待处理', action: '修正数据' }, { id: 4, type: '督办', title: '跟进肥西县水稻收获进度', region: '肥西县', content: '当前进度低于序时进度，请反馈原因和措施。', date: '2026-10-10', status: '已完成', action: '查看记录' }, { id: 5, type: '政策', title: '实际种粮农民补贴申报提醒', region: '全省', content: '请及时关注补贴政策和申报时间。', date: '2026-10-08', status: '已完成', action: '查看政策' }, { id: 6, type: '灾情', title: '低温阴雨灾害风险提示', region: '阜阳市', content: '请做好田间排水和秋粮抢收。', date: '2026-10-07', status: '已完成', action: '查看详情' }]); const filtered = computed(() => tasks.value.filter(item => tab.value === 'all' || (tab.value === 'todo' ? item.status === '待处理' : item.status === '已完成'))); const pending = computed(() => tasks.value.filter(item => item.status === '待处理').length); const done = computed(() => tasks.value.filter(item => item.status === '已完成').length); const handle = task => { if (task.status === '待处理') { task.status = '已完成'; ElMessage.success('任务已完成') } else ElMessage.info('已打开任务详情') }
</script>
